declare(strict_types=1);require_once dirname(__DIR__).'/src/bootstrap.php';Auth::requireOwner();$q=trim((string)($_GET['q']??''));$like='%'.$q.'%';$opps=[];$projects=[];$customers=[];$tasks=[];$agents=[];if($q!==''){$s=db()->prepare("SELECT id,title,source,status,score FROM opportunities WHERE title LIKE ? OR client_name LIKE ? OR requirements_text LIKE ? ORDER BY score DESC,id DESC LIMIT 30");$s->execute([$like,$like,$like]);$opps=$s->fetchAll();$s=db()->prepare("SELECT id,name,primary_domain,workflow_stage,status FROM projects WHERE name LIKE ? OR primary_domain LIKE ? ORDER BY updated_at DESC LIMIT 30");$s->execute([$like,$like]);$projects=$s->fetchAll();$s=db()->prepare("SELECT id,display_name,phone,email,status FROM customers WHERE display_name LIKE ? OR phone LIKE ? OR email LIKE ? ORDER BY updated_at DESC LIMIT 30");$s->execute([$like,$like,$like]);$customers=$s->fetchAll();$s=db()->prepare("SELECT t.id,t.title,t.status,p.name project_name,a.display_name agent_name FROM tasks t LEFT JOIN projects p ON p.id=t.project_id LEFT JOIN agents a ON a.id=t.assigned_agent_id WHERE t.title LIKE ? OR t.description LIKE ? ORDER BY t.id DESC LIMIT 30");$s->execute([$like,$like]);$tasks=$s->fetchAll();$s=db()->prepare("SELECT id,slug,display_name,role_title,status FROM agents WHERE display_name LIKE ? OR role_title LIKE ? OR specialty LIKE ? ORDER BY id LIMIT 30");$s->execute([$like,$like,$like]);$agents=$s->fetchAll();}
AdminUi::header('البحث الشامل','dashboard');echo AdminUi::flash();?>
