<section class="card span-6"><div class="card-title"><h2>العملاء (<?=count($customers)?>)</h2></div><?php foreach($customers as $x):?><a class="search-result" href="customers.php?id=<?=$x['id']?>"><div><b><?=e($x['display_name']?:'عميل #'.$x['id'])?></b><small><?=e($x['phone']?:$x['email']?:'—')?></small></div><?=AdminUi::badge($x['status'])?></a><?php endforeach?><?php if(!$customers)echo AdminUi::empty('لا نتائج.')?></section>
<section class="card span-6"><div class="card-title"><h2>المهام (<?=count($tasks)?>)</h2></div><?php foreach($tasks as $x):?><a class="search-result" href="tasks.php?id=<?=$x['id']?>"><div><b>#<?=$x['id']?> <?=e($x['title'])?></b><small><?=e($x['project_name']?:'بدون مشروع')?> · <?=e($x['agent_name']?:'—')?></small></div><?=AdminUi::badge($x['status'])?></a><?php endforeach?><?php if(!$tasks)echo AdminUi::empty('لا نتائج.')?></section>
<section class="card span-12"><div class="card-title"><h2>الوكلاء (<?=count($agents)?>)</h2></div><div class="source-grid"><?php foreach($agents as $x):?><a class="source-card" href="agent-profile.php?slug=<?=e($x['slug'])?>"><div class="card-title"><b><?=e($x['display_name'])?></b><?=AdminUi::badge($x['status'])?></div><small><?=e($x['role_title'])?></small></a><?php endforeach?></div></section></div><?php endif?>
